// FUNCTION: BFME2 0x00133AD0 size=159 name=?Set_View_Plane@CameraClass@@QAEXMM@Z evidence=N:ledger tier=B hypothesis:Z
void CameraClass::Set_View_Plane(float hfov, float vfov)
{
	float half_w = tan(hfov * 0.5);
	float half_h;

	// A vertical angle of -1 means "keep the aspect ratio".
	if (vfov == -1.0f) {
		half_h = (1.0f / AspectRatio) * half_w;
	} else {
		half_h = tan(vfov * 0.5);
		AspectRatio = half_w / half_h;
	}

	ViewPlane.Min.Set(-half_w, -half_h);
	ViewPlane.Max.Set(half_w, half_h);
	FrustumValid = false;
}

// FUNCTION: BFME2 0x00133B70 size=76 name=?Set_Aspect_Ratio@CameraClass@@QAEXM@Z evidence=N:ledger tier=B hypothesis:Z
void CameraClass::Set_Aspect_Ratio(float ratio)
{
	AspectRatio = ratio;
	float inv_ratio = 1.0f / ratio;
	ViewPlane.Min.Y = ViewPlane.Min.X * inv_ratio;
	ViewPlane.Max.Y = ViewPlane.Max.X * inv_ratio;
	FrustumValid = false;
}

// FUNCTION: BFME2 0x00133BC0 size=313 name=?Un_Project@CameraClass@@QBEXAAVVector3@@ABVVector2@@@Z evidence=N:ledger tier=B hypothesis:Z
void CameraClass::Un_Project(Vector3 & dest,const Vector2 & view_point) const
{
	/*
	** map view_point.X from -1..1 to ViewPlaneMin.X..ViewPlaneMax.X
	** map view_point.Y from -1..1 to ViewPlaneMin.X..ViewPlaneMax.X
	*/
	float vpdx = ViewPlane.Max.X - ViewPlane.Min.X;
	float vpdy = ViewPlane.Max.Y - ViewPlane.Min.Y;

	Vector3 point;
	point.X = ViewPlane.Min.X + vpdx * (view_point.X + 1.0f) * 0.5f;
	point.Y = ViewPlane.Min.Y + vpdy * (view_point.Y + 1.0f) * 0.5f;
	point.Z = -1.0f;

	Matrix3D::Transform_Vector(Transform,point,&dest);
}

