void CameraClass::Convert_Old(Vector3 &point)
{
	// Old cameras used -1..1 view coordinates; map them to 0..1.
	point.X = (point.X + 1.0f) * 0.5f;
	point.Y = (point.Y + 1.0f) * 0.5f;
}

