// FUNCTION: BFME2 0x001348C0 size=285 name=?Get_D3D_Projection_Matrix@CameraClass@@QAEXPAVMatrix4x4@@@Z evidence=N:ledger tier=B hypothesis:K
void CameraClass::Get_D3D_Projection_Matrix(Matrix4x4 *out_matrix)
{
	Update_Frustum();
	*out_matrix = ProjectionTransform;

	// D3D wants depth in 0..1 rather than -1..1: rewrite the z row.
	float inv_depth = 1.0 / (ZFar - ZNear);
	if (Projection == PERSPECTIVE) {
		(*out_matrix)[2][2] = -(ZFar * inv_depth);
		float far_times_near = ZFar * ZNear;
		(*out_matrix)[2][3] = -(far_times_near * inv_depth);
	} else {
		(*out_matrix)[2][2] = -inv_depth;
		(*out_matrix)[2][3] = -(inv_depth * ZNear);
	}
}

