bool CameraClass::Cull_Sphere(const SphereClass &sphere) const
{
	Update_Frustum();
	return CollisionMath::Overlap_Test(Frustum, sphere) == CollisionMath::OUTSIDE;
}

// FUNCTION: BFME2 0x00135990 size=214 name=?Cull_Box@CameraClass@@UBE_NABVAABoxClass@@@Z evidence=N:ledger tier=B hypothesis:cohesion
bool CameraClass::Cull_Box(const AABoxClass &box) const
{
	Update_Frustum();
	for (int i = 0; i < 6; i++)
	{
		const PlaneClass &plane = Frustum.Planes[i];
		Vector3 farpt;
		get_far_extent(plane.N, box.Extent, &farpt);
		Vector3 negfarpt(box.Center.X - farpt.X, box.Center.Y - farpt.Y, box.Center.Z - farpt.Z);
		if (CollisionMath::Overlap_Test(plane, negfarpt) == CollisionMath::POS)
		{
			return true;
		}
	}
	return false;
}

// FUNCTION: BFME2 0x00135A70 size=866 name=?Apply@CameraClass@@QAEXXZ evidence=N:ledger tier=B hypothesis:Z
void CameraClass::Apply(void)
{
	Update_Frustum();

	int width, height, bits;
	bool windowed;
	WW3D::Get_Render_Target_Resolution(width, height, bits, windowed);

	D3DVIEWPORT9 vp;
	vp.X = (DWORD)(Viewport.Min.X * (float)width);
	vp.Y = (DWORD)(Viewport.Min.Y * (float)height);
	vp.Width = (DWORD)((Viewport.Max.X - Viewport.Min.X) * (float)width);
	vp.Height = (DWORD)((Viewport.Max.Y - Viewport.Min.Y) * (float)height);
	vp.MinZ = ZBufferMin;
	vp.MaxZ = ZBufferMax;
	DXWrapper::Set_Viewport(&vp);

	Matrix4x4 d3dprojection;
	if (bfmeCameraProjectionOverride) {
		d3dprojection = ReflectedProjectionTransform.Transpose();
	} else {
		Get_D3D_Projection_Matrix(&d3dprojection);
	}
	DXWrapper::Set_Projection_Transform_With_Z_Bias(d3dprojection, ZNear, ZFar);
	DXWrapper::Set_Transform(D3DTS_VIEW, Matrix4x4(CameraInvTransform));
}

